INSERT INTO audit_events VALUES(6102,'2026-08-23 10:49:32','7d62acc4-754','builder','/home/iconbaypark2900/openworker-workspace/opensciencelab','','replace_in_file','proposed','','','{"path": "opensciencelab/base.py", "old": "@dataclass\\nclass Bundle:\\n    \"\"\"What every adapter returns: artifacts, manifest patch, cost by tier.\"\"\"\\n\\n    artifacts: List[Artifact] = field(default_factory=list)\\n    manifest_patch: Dict[str, Any] = field(default_factory=dict)\\n    cost: Dict[int, float] = field(\\n        default_factory=lambda: {TIER_ZERO: 0.0, TIER_ONE: 0.0, TIER_TWO: 0.0}\\n    )\\n\\n    def total_cost(self) -> float:\\n        return sum(self.cost.values())", "new": "@dataclass\\nclass Bundle:\\n    \"\"\"What every adapter returns: artifacts, manifest patch, cost by tier.\\n\\n    ``cost`` is what the call ACTUALLY spent, per tier. ``predicted_cost`` is\\n    what the call declared it would be allowed to spend, quoted up-front from\\n    the declared limits (before a single evaluation runs). ``delta_cost`` is\\n    actual ``-`` predicted: legitimately negative when a search exits early\\n    (e.g. a plateau kill), and that gap is why the delta is recorded instead\\n..."}','','','');
