INSERT INTO audit_events VALUES(7839,'2026-08-24 06:03:29','55b259f3-f8a','builder','/home/iconbaypark2900/openworker-workspace/opensciencelab','','replace_in_file','proposed','','','{"new": "# --------------------------------------------------------------------------- #\\n# Optional RDKit / meeko -- both stay importable even when neither is installed.\\n#\\n# The flag pair (_HAVE_RDKIT, _HAVE_MEKOO) is the single source of truth:\\n# every consumer checks them, never the module globals. (A module-level\\n# ``X = None`` in an except clause is fine at import time -- the module\\n# simply stays importable -- but keeping the flags canonical means a host\\n# without RDKit degrades by flag, s...", "old": "# --------------------------------------------------------------------------- #\\n# Optional RDKit / meeko -- both stay importable even when neither is installed.\\n#\\n# IMPORTANT: except branches must NOT bind these module-level names (Chem /\\n# AllChem / Descriptors / _RdkitQED / MoleculePreparation / PDBQTWriterLegacy)\\n# to None -- assigning any name inside an except makes Python treat it as a\\n# local at module scope in a way that shadows the module attribute for any\\n# function that refer...", "path": "opensciencelab/descriptors.py"}','','','');
INSERT INTO audit_events VALUES(7840,'2026-08-24 06:03:29','55b259f3-f8a','builder','/home/iconbaypark2900/openworker-workspace/opensciencelab','','replace_in_file','proposed','','','{"new": "# SA_Score lives at rdkit.Chem.SA_Score in older releases and under\\n# rdkit.Contrib.SA_Score in newer ones (both ship sascorer); the function name\\n# is sas() in the former and calculateScore() in the latter. We probe both\\n# sites and expose a single callable _rdkit_sa_score(mol), or None when both\\n# are gone, in which case descriptor_bank falls back to the bundled sa proxy.", "old": "# SA_Score lives at rkit.Chem.SA_Score in older releases and under\\n# rkit.Contrib.SA_Score in newer ones (both ship sascorer); the function name\\n# shifted to calculateScore() in the Contrib copy. We probe both sites and\\n# expose a single callable _rdkit_sa_score(mol) or None when both are gone,\\n# in which case descriptor_bank falls back to the bundled sa proxy.", "path": "opensciencelab/descriptors.py"}','','','');
