INSERT INTO audit_events VALUES(10418,'2026-08-25 17:57:37','6ac5ea43-b0c','builder','/home/iconbaypark2900/openworker-workspace/opensciencelab','','replace_in_file','proposed','','','{"new": "  # --interactive=false keeps the run safe on TTY-less hosts (CI); capture the\\n  # exit code rather than letting `set -e` hide it after the image printed.\\n  set +e\\n  docker run --rm --interactive=false \\\\n    -v \"$(pwd)/runs:/app/runs\" \\\\n    -e \"VINA_RECEPTOR_PDBQT=/app/data/receptor.pdbqt\" \\\\n    \"${VIMAGE}\"\\n  rc=$?\\n  set -e\\n  [ \"${rc}\" -eq 0 ] && echo \"-- exit code: 0 (all gates green)\" \\\\n    || echo \"-- exit code: ${rc} (gates red -- see manifest in runs/)\"\\n  exit \"${rc}\"\\nfi", "old": "  # --interactive=false keeps the run safe on TTY-less hosts (CI): docker-run\\n  # passes through the caller''s stdin, which -i would have consumed.\\n  docker run --rm --interactive=false \\\\n    -v \"$(pwd)/runs:/app/runs\" \\\\n    -e \"VINA_RECEPTOR_PDBQT=/app/data/receptor.pdbqt\" \\\\n    \"${VIMAGE}\"\\n  echo \"-- exit code: $?\"\\n  exit 0\\nfi", "path": "docker/docker-run.sh"}','','','');
