INSERT INTO audit_events VALUES(18606,'2026-08-28 16:19:43','913b86ac-2e9','builder','/home/iconbaypark2900/dataScience/metered-web-broker','','replace_in_file','proposed','','','{"new": "WORKDIR /app\\n\\n# 1. Copy the workspace sources first, so `npm ci` can see every workspace\\n#    member and create the `@mwb/*` workspace symlinks in node_modules.\\nCOPY packages ./packages\\n\\n# 2. Install dependencies. Lockfile-first: package.json / package-lock.json\\n#    must be copied (or at least present) before `npm ci`.\\nCOPY package.json package-lock.json ./\\nRUN npm ci\\n\\n# 3. Serve. WORKDIR is the gateway package so `tsx` resolves the @mwb/*\\n#    workspace symlinks and runs package...", "old": "WORKDIR /app\\n\\n# 1. Install dependencies first so this layer is cached across code changes.\\nCOPY package.json package-lock.json ./\\nRUN npm ci\\n\\n# 2. Copy the source (the packages and the gateway entrypoint).\\nCOPY packages ./packages\\n\\n# 3. Serve. WORKDIR is the gateway package so `tsx` resolves the @mwb/*\\n#    workspace symlinks and runs packages/gateway/src/server.ts directly.\\n#    PORT is env-driven; see DEPLOY.md for options.\\nWORKDIR /app/packages/gateway\\nENV PORT=8787", "path": "packages/gateway/docker/Dockerfile"}','','','');
