INSERT INTO audit_events VALUES(23620,'2026-08-30 20:04:21','52b4435c-621','builder','/home/iconbaypark2900/dataScience/agpack','','replace_in_file','proposed','','','{"new": "def test_equivalent_rejects_tampered_raw_value():\\n    \"\"\"`assert_equivalent` rejects an envelope whose *raw bytes* do not match\\n    across engines \u2014 it compares raw_value positionally, so a value that was\\n    altered by a \"runtime\" is caught (the tamper-check on the fingerprint\\n    itself lives in _unwrap).\"\"\"\\n    value = b\"value\"\\n    tampered = b\"value-modified\"\\n    result = _result([[tampered], [value]])\\n    with pytest.raises(PortabilityViolation):\\n        assert_equivalent(result)", "old": "def test_equivalent_rejects_malformed_envelope():\\n    \"\"\"`assert_equivalent` rejects an envelope whose fingerprint does not match\\n    its value \u2014 a tampered envelope is not silently tolerated.\"\"\"\\n    value = b\"value\"\\n    tampered = b\"DFD#1700000000000:deadbeefdeadbeef:\" + value\\n    result = _result([[tampered], [value]])\\n    with pytest.raises(PortabilityViolation):\\n        assert_equivalent(result)", "path": "tests/test_portability_proof.py"}','','','');
