INSERT INTO audit_events VALUES(27107,'2026-08-31 23:47:36','1f1701d7-ca5','builder','/home/iconbaypark2900/jabCreative/dataScience/concordCircuit','','replace_in_file','proposed','','','{"new": "def _verify_invariant(path: str) -> tuple[bool, str]:\\n    \"\"\"The ledger self-validates via real ``replay`` and ``sum == delta``.\\n\\n    Reads the JSONL written by ``build`` back from disk (the auditor''s\\n    read-back path) and reconstructs the real ``AuditLedger`` from it, so a\\n    corrupt file is caught here -- not only in a fresh in-memory build.\\n    \"\"\"\\n\\n    try:\\n        sl = read_ledger(path)\\n        records = sl.records\\n    except FileNotFoundError:\\n        return False, f\"ledg...", "old": "def _verify_invariant(path: str) -> tuple[bool, str]:\\n    \"\"\"The ledger self-validates via real ``replay`` and ``sum == delta``.\"\"\"\\n\\n    corpus = build_corpus()\\n    records = build_ledger(corpus).records\\n\\n    ok, err = _replay_all(records)\\n    if not ok:\\n        return False, f\"replay raised: {err}\"\\n\\n    # round-trip through JSONL + reconstruct + replay again (auditor path)\\n    recs, _count = from_jsonl(to_jsonl(records))\\n    try:\\n        replay(reconstruct_ledger(recs))\\n    exc...", "path": "concord/__main__.py"}','','','');
